  xAxis: { type: 'category', data: rows.map((row) => row.part), axisLabel: { interval: 0, fontSize: 11 } },
  yAxis: { type: 'value', name: '元/股', splitLine: { lineStyle: { color: '#edf0f4' } } },
  series: [
